export function parseLines(text: string): unknown[] {
  // A UTF-8 BOM is only meaningful at the very start of the input and is
  // treated as part of the first physical line, not as content.
  const body = text.charCodeAt(0) === 0xfeff ? text.slice(1) : text
  const rows: unknown[] = []
  const lines = body.split(/\r?\n/)
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]
    if (line.trim() === "") continue
    try {
      rows.push(JSON.parse(line))
    } catch (error) {
      const detail = error instanceof Error ? `: ${error.message}` : ""
      throw new Error(`Invalid JSON on line ${i + 1}${detail}`)
    }
  }
  return rows
}
